WFJ.Data.add("gossip", {
  ["cb008bdf121f8687"] = { "Oh sì, antico, Hakkar è tornato. Presto il mondo crollerà sotto la sua potenza. Consumato. Ridotto in rovina...", "." },
  ["cb03c6ecad10fb18"] = { "È tutto quello che sai fare?", "." },
  ["cb0561eac52632b2"] = { "Ah, tu! Ho dei compiti da affidare, e non ho bisogno di perdere tempo a spiegarne l'importanza cruciale. Ascolta bene.", "." },
  ["cb0ea0d318a76eca"] = { "Uno degli Ash'ari Crystals è stato distrutto! Uccidete gli intrusi!", "." },
  ["cb1556bdd47bac4f"] = { "La ⟦Stonewrought Dam=Diga di Pietrasalda⟧ è salva! Tre urrà per {name}!", "." },
  ["cb163975270bc963"] = { "Sta' attento, Antonio.", "." },
  ["cb170fbfc71ed278"] = { "Mamma? Posso accarezzare Fizzles?", "." },
  ["cb1daa7e11c31084"] = { "Dove posso trovare frammenti d'osso?", "." },
  ["cb247bd0f25da945"] = { "Che bella giornata per le corse! Oh, ma chi voglio prendere in giro? Ogni giorno è una bella giornata per le corse!", "." },
  ["cb28c47dc4c26121"] = { "Potrei avere una copia di «⟦The Feast of Winter Veil=Vigilia di Grande Inverno⟧» da leggere?", "." },
  ["cb2a72993cb4201c"] = { "Ora tornatene a casa, dove devi stare!", "." },
  ["cb2ae403a0edc651"] = { "Celebras, ho perso il mio Scettro...", "." },
  ["cb31c9cd25b67333"] = { "Sono l'ultima incarnazione dei venditori automatici... un giorno domineremo il mondo... non dire al mio capo che faccio la cresta sulla sua merce...", "." },
  ["cb3257c6f40ff1f7"] = { "Fai un salto al Blue Recluse. Dove tutti conoscono il tuo nome!", "." },
  ["cb32fd9cc5e83d57"] = { "Ottima scelta. Ho segnato quel luogo sulla tua mappa.", "." },
  ["cb339cb65cd964b3"] = { "Presto faremo tornare gli Dei Antichi.", "." },
  ["cb39a807bd8a06af"] = { "Credi che il padrone si lasci intimorire dai tuoi giochetti? Non cadremo mai per mano tua!", "." },
  ["cb409d78c6e15079"] = { "Magari... potresti portarmi in braccio?", "." },
  ["cb432899dddc5494"] = { "La tua mente non è concentrata. Mi stai nascondendo qualcosa?", "." },
  ["cb43e5378d1878f1"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo conquisterà!", "." },
  ["cb45fbd4306ea85f"] = { "Oh, vuoi imparare a raccogliere margheritine, eh? Ah! Ti sto solo prendendo in giro, <ragazzo/ragazza>.\n\nÈ una bella professione, e Reyna Stonebranch può mostrarti come si fa. Lavora all'Ironforge Physician, sul lato sud della ⟦Great Forge=Grande Forgia⟧, qui a ⟦Ironforge=Forgiardente⟧.", "." },
  ["cb538c52d1ea4a55"] = { "%s lancia uno strillo e chiama aiuto!", "." },
  ["cb59ea7799983482"] = { "Oh, che cosa assolutamente deliziosa!", "." },
  ["cb5cd7b98e80c235"] = { "Oh... non ho mai visto niente del genere...", "." },
  ["cb5fae704ced895a"] = { "Apri la tua mente, viandante, e cominceremo.", "." },
  ["cb60e184345828fa"] = { "In realtà anch'io sto ancora imparando. L'esperta è Rhiannon. È lì, vicino alle casse. Puoi imparare molto da lei.", "." },
  ["cb6ec7510c3ca0c0"] = { "Non posso aiutarti finché non avrai appreso di più sulle basi. Torna da me quando sarai <pronto/pronta>.", "." },
  ["cb74f02ebf151f3d"] = { "Se non sapessi come stanno le cose, penserei che mi stai prendendo in giro, mortale; ma sì, è per lo più corretto. Puoi restare completamente <vestito/vestita>.", "." },
  ["cb82772153bd26a2"] = { "Continua, per favore.", "." },
  ["cb833365167dae8f"] = { "Il nostro maestro Malfurion resta perduto nel Sogno, {class}. La sua è la luce di un faro che ci indica la via, e dobbiamo fare tutto ciò che è in nostro potere per preservarla.", "." },
  ["cb8eb0440a902e7b"] = { "Il cibo! Ecco un argomento in cui posso affondare le zanne! Mi dicono che abbiamo messo in ghiaccio e da parte $2095w Controfiletti di Lupo su $2096w, $2102w Pinnagialla Maculato al Vapore su $2103w e $2105w Salmoni Impanati su $2106w.", "." },
  ["cb9c194ea4f294df"] = { "Temo di no, {name}. Ora senti la vergogna che hai attirato su di te.", "." },
  ["cba07f3bb879e0eb"] = { "Il numero dei miei compagni si riduce, dea, e presto il mio potere non basterà più a trattenere i demoni di ⟦Felwood=Vilbosco⟧.", "." },
  ["cba6baffb0eb833c"] = { "Salute, {class}. Sono Exzhal, Servitore di Rastakhan.", "." },
  ["cbb8cc1221667239"] = { "Ah, sei gentile, amico, ma abbiamo già tutto il cuoio pesante che ci serve. E scommetto che il tuo coltello è ancora affilato. Magari puoi usarlo per aiutare gli altri con le loro raccolte, no? Buona giornata!", "." },
  ["cbbd31ff17b35f8c"] = { "Mentre le tossine annidate a Maraudon mi penetravano nella mente, cominciai a perdere il contatto con la realtà. Temendo che lo scettro venisse usato per il male, le mie sorelle driadi me lo sottrassero di nascosto, lo spezzarono in due parti e lo nascosero nelle caverne.\n\nPresto anche loro caddero vittime della follia, e le due parti dello scettro, rimaste incustodite, finirono nelle mani di Vyletongue in persona. Il satiro ne affidò una parte a Noxxion, un malvagio elementale, e l'altra la tiene ancora oggi.", "." },
  ["cbbf0c3957f116d8"] = { "Ormai è finita, restano solo le lacrime. Tutto il materiale bellico viene trasportato alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e arriverà in meno di $2113w giorni. Non manca molto prima che lo scettro sia ricomposto e la guerra cominci finalmente.", "." },
  ["cbbfb3488d820936"] = { "Gli assassini sono qui! Presto, prima che raggiungano il magistrato!", "." },
  ["cbc1e83ae6203520"] = { "Non stai solo facendo perdere tempo ai tuoi compagni di studio, stai facendo perdere tempo anche a me.", "." },
  ["cbcc136a5c6ab52f"] = { "Ohè! Cerchi addestramento nella via del guerriero, eh? Kelstrum Stonebreaker ti farà sudare! Basta che tu marci fino al Salone delle Armi, a est dei cancelli di ⟦Ironforge=Forgiardente⟧.", "." },
  ["cbd585a35d7d7541"] = { "La battaglia infuria, e sia il nostro capitano sia quello del nemico sono caduti!\n\nOra Drek'Thar ci guida dalla ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧, e il nano Vanndar Stormpike si nasconde nel profondo di Dun Baldar. Sconfiggi Vanndar e conquista la vittoria per l'⟦Horde=Orda⟧!", "." },
  ["cbe36745a181a856"] = { "Piagnone! Piagnone!", "." },
  ["cbebe5a9504cf573"] = { "Salute, {class}! Ho un solo obiettivo: catalogare e registrare tutto il sapere legato alla storia di ⟦Duskwood=Boscovespro⟧ e ⟦Darkshire=Borgoscuro⟧. Forse potresti aiutarmi nella mia impresa?", "." },
  ["cbeea509e2e5009d"] = { "Non dimenticate gli orfani di ⟦Stormwind=Roccavento⟧!", "." },
  ["cbf01e618c4754e7"] = { "Qui a Darnassus troverai istruttori esperti che hanno perfezionato le arti della loro classe in secoli di addestramento e dedizione. Ti guiderò da uno che possa diventare il tuo mentore: devi solo dirmi il cammino che hai scelto.", "." },
  ["cbf4d7c1cf09058c"] = { "Oh, andremo proprio d'accordo, {name}.", "." },
  ["cbfa6ba39603fe95"] = { "Oggi sbucano da tutte le parti. Continuiamo a muoverci, o potremmo trovare altre creature che vogliono la mia pelle.", "." },
})
